create or replace function public.enforce_recruiter_seat_limit() returns trigger language plpgsql security definer set search_path=public as $$ declare lim int; cnt int; begin if new.company_id is null or new.role not in ('owner','manager','recruiter') then return new; end if; select p.recruiter_limit into lim from public.company_subscriptions s join public.saas_plans p on p.code=s.plan_code where s.company_id=new.company_id and (s.status='active' or (s.status='trialing' and s.trial_ends_at>now())); if lim is null then return new; end if; select count(*) into cnt from public.profiles where company_id=new.company_id and role in ('owner','manager','recruiter') and id<>new.id; if lim>=0 and cnt>=lim then raise exception 'Recruiter seat plan limit reached'; end if; return new; end $$; revoke all on function public.enforce_recruiter_seat_limit() from public,anon,authenticated; drop trigger if exists enforce_recruiter_seat_limit on public.profiles; create trigger enforce_recruiter_seat_limit before insert or update of company_id,role on public.profiles for each row execute function public.enforce_recruiter_seat_limit();
